import Foundation

var failures=0
func check(_ ok: Bool,_ name: String) { print((ok ? "PASS " : "FAIL ")+name); if !ok { failures += 1 } }
check(BuildID.parseCommit("commit=abc\ncommit=def") == nil,"conflicting identities refused")
check(BuildID.parseCommit("commit=abc\ncommit=") == nil,"later malformed entry refused")
check(BuildID.parseCommit("commit=abc\ncommit=abc") == "abc","same duplicate accepted")
check(BuildID.parseCommit("other=x\ncommit=abc") == "abc","legacy grammar retained")

for text in ["commit=abc\ncommit=def","commit=def\ncommit=abc","commit=abc\ncommit=","commit=\ncommit=abc","commit=abc\ncommit=a b","commit=a\tb\ncommit=abc","commit=abc\r\ncommit=def","commit=abc\ncommit=abc\ncommit=def"] {
 check(BuildID.parseCommit(text) == nil,"all entries scanned conflicts/malformed fail closed")
}
for text in ["commit=abc"," commit=abc ","\tcommit= abc\t","\ncommit=abc\r\ncommit=abc\r","other=x\ncommit=abc\nignored=y"] {
 check(BuildID.parseCommit(text) == "abc","legacy whitespace and duplicate grammar")
}
for opaque in ["not-a-git-hash","1234567","abc=def","!opaque!?","çığ"] {
 check(BuildID.parseCommit("commit="+opaque+"\ncommit="+opaque) == opaque,"opaque identity preserved")
}
for text in ["","other=x","commit=","commit=  ","Commit=abc","commit =abc"] {
 check(BuildID.parseCommit(text) == nil,"no usable exact commit key")
}
check(BuildID.shortValue("1234567890") == "1234567" && BuildID.shortValue("abc") == "abc" && BuildID.shortValue(BuildID.unknown) == "unknown","short format preserved")
check(BuildID.logLine("opaque") == "[GOR] build-id opaque","launch log format preserved")
let emptyBundlePath=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".bundle")
try! FileManager.default.createDirectory(at:emptyBundlePath,withIntermediateDirectories:true)
defer { try? FileManager.default.removeItem(at:emptyBundlePath) }
if let bundle=Bundle(path:emptyBundlePath.path) {check(BuildID.value(bundle:bundle) == BuildID.unknown,"missing bundle identity unknown")} else {check(false,"test bundle created")}

print("semantic failures=\(failures)")
exit(failures == 0 ? 0 : 1)
